692	(* ************************** *)
693	(* *****   Lagrangian   ***** *)
694	(* ************************** *)
695	
696	LGauge := Block[{mu,nu,ii,aa}, 
697	  ExpandIndices[-1/4 FS[B,mu,nu] FS[B,mu,nu] - 1/4 FS[Wi,mu,nu,ii] FS[Wi,mu,nu,ii] - 1/4 FS[G,mu,nu,aa] FS[G,mu,nu,aa], FlavorExpand->SU2W]];
698	
699	LFermions := Block[{mu}, 
700	  ExpandIndices[I*(
701	    QLbar.Ga[mu].DC[QL, mu] + LLbar.Ga[mu].DC[LL, mu] + uRbar.Ga[mu].DC[uR, mu] + dRbar.Ga[mu].DC[dR, mu] + lRbar.Ga[mu].DC[lR, mu]), 
702	  FlavorExpand->{SU2W,SU2D}]/.{CKM[a_,b_] Conjugate[CKM[a_,c_]]->IndexDelta[b,c], CKM[b_,a_] Conjugate[CKM[c_,a_]]->IndexDelta[b,c]}];
703	
704	LHiggs := Block[{ii,mu, feynmangaugerules},
705	  feynmangaugerules = If[Not[FeynmanGauge], {G0|GP|GPbar ->0}, {}];
706	 
707	  ExpandIndices[DC[Phibar[ii],mu] DC[Phi[ii],mu] + muH^2 Phibar[ii] Phi[ii] - lam Phibar[ii] Phi[ii] Phibar[jj] Phi[jj], FlavorExpand->{SU2D,SU2W}]/.feynmangaugerules
708	 ];
709	
710	LYukawa := Block[{sp,ii,jj,cc,ff1,ff2,ff3,yuk,feynmangaugerules},
711	  feynmangaugerules = If[Not[FeynmanGauge], {G0|GP|GPbar ->0}, {}];
712	 
713	  yuk = ExpandIndices[
714	   -yd[ff2, ff3] CKM[ff1, ff2] QLbar[sp, ii, ff1, cc].dR [sp, ff3, cc] Phi[ii] - 
715	    yl[ff1, ff3] LLbar[sp, ii, ff1].lR [sp, ff3] Phi[ii] - 
716	    yu[ff1, ff2] QLbar[sp, ii, ff1, cc].uR [sp, ff2, cc] Phibar[jj] Eps[ii, jj], FlavorExpand -> SU2D];
717	  yuk = yuk /. { CKM[a_, b_] Conjugate[CKM[a_, c_]] -> IndexDelta[b, c], CKM[b_, a_] Conjugate[CKM[c_, a_]] -> IndexDelta[b, c]};
718	  yuk+HC[yuk]/.feynmangaugerules
719	 ];
720	
721	LGhost := Block[{LGh1,LGhw,LGhs,LGhphi,mu, generators,gh,ghbar,Vectorize,phi1,phi2,togoldstones,doublet,doublet0},
722	  (* Pure gauge piece *) 	
723	  LGh1 = -ghBbar.del[DC[ghB,mu],mu];
724	  LGhw = -ghWibar[ii].del[DC[ghWi[ii],mu],mu];
725	  LGhs = -ghGbar[ii].del[DC[ghG[ii],mu],mu];
726	
727	  (* Scalar pieces: see Peskin pages 739-742 *)
728	  (* phi1 and phi2 are the real degrees of freedom of GP *)
729	  (* Vectorize transforms a doublet in a vector in the phi-basis, i.e. the basis of real degrees of freedom *)
730	  gh    = {ghB, ghWi[1], ghWi[2], ghWi[3]};
731	  ghbar = {ghBbar, ghWibar[1], ghWibar[2], ghWibar[3]};
732	  generators = {-I/2 g1 IdentityMatrix[2], -I/2 gw PauliSigma[1], -I/2 gw PauliSigma[2], -I/2 gw PauliSigma[3]};
733	  doublet = Expand[{(-I phi1 - phi2)/Sqrt[2], Phi[2]} /. MR$Definitions /. vev -> 0]; 
734	  doublet0 = {0, vev/Sqrt[2]};
735	  Vectorize[{a_, b_}]:= Simplify[{Sqrt[2] Re[Expand[a]], Sqrt[2] Im[Expand[a]], Sqrt[2] Re[Expand[b]], Sqrt[2] Im[Expand[b]]}/.{Im[_]->0, Re[num_]->num}];
736	  togoldstones := {phi1 -> (GP + GPbar)/Sqrt[2], phi2 -> (-GP + GPbar)/(I Sqrt[2])};
737	  LGhphi=Plus@@Flatten[Table[-ghbar[[kkk]].gh[[lll]] Vectorize[generators[[kkk]].doublet0].Vectorize[generators[[lll]].(doublet+doublet0)],{kkk,4},{lll,4}]] /.togoldstones;
738	
739	ExpandIndices[ LGhs + If[FeynmanGauge, LGh1 + LGhw + LGhphi,0], FlavorExpand->SU2W]];
740	
741	LSM:= LGauge + LFermions + LHiggs + LYukawa + LGhost;
742	
